import React, { useState, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import styles from '../css/chat.module.css';

const Chat = () => {
  const location = useLocation();
  const { personality, name: chatbotName = '챗봇' } = location.state || {};  // '/settings'에서 전달된 값
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [currentDateTime, setCurrentDateTime] = useState('');
  const [error, setError] = useState(null);
  const [isRecording, setIsRecording] = useState(false);  // 음성 녹음 상태
  const [audioHtml, setAudioHtml] = useState(null);  // TTS 음성 HTML
  const chatEndRef = useRef(null);  // 맨 밑의 메시지 참조용
  const mediaRecorderRef = useRef(null);  // 음성 녹음을 위한 MediaRecorder

  // 현재 날짜와 시간을 반환하는 함수 (날짜 + 시:분 형식)
  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',  // 요일을 포함하도록 설정
    });
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false, // 24시간 형식
    });

    return `${date} ${time}`; // 예: "2025년 1월 11일 금요일 15:05"
  };

  // 전송한 시간과 응답받은 시간에서 날짜는 제외하고 시:분만 표시
  const getTimeOnly = () => {
    const now = new Date();
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false, // 24시간 형식
    });
    return time; // 예: "15:05"
  };

  // 음성 녹음 시작
  const startRecording = () => {
    if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
      navigator.mediaDevices.getUserMedia({ audio: true })
        .then((stream) => {
          mediaRecorderRef.current = new MediaRecorder(stream);
          const audioChunks = [];

          mediaRecorderRef.current.ondataavailable = (event) => {
            audioChunks.push(event.data);
          };

          mediaRecorderRef.current.onstop = async () => {
            const audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
            const audioData = await audioBlob.arrayBuffer();

            const formData = new FormData();
            formData.append('file', new Blob([audioData]), 'audio.wav');

            // 서버로 음성 파일 전송
            try {
              const response = await fetch(`${process.env.REACT_APP_API_URL}/chat-audio`, {
                method: 'POST',
                body: formData,
              });

              if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.detail || "오류가 발생했습니다.");
              }

              const data = await response.json();
              const chatbotMessage = data.response;
              const audioHtml = data.audio_html; // TTS 음성 HTML
              const recognizedText = data.transcript;  // 서버에서 음성 텍스트 결과 받기

              // 사용자 메시지로 추가
              const sentTime = getTimeOnly();
              setChatHistory((prevHistory) => [
                ...prevHistory,
                { sender: "사용자", message: recognizedText, time: sentTime },
              ]);

              // 챗봇 응답 추가
              const receivedTime = getTimeOnly();
              setChatHistory((prevHistory) => [
                ...prevHistory,
                { sender: chatbotName, message: chatbotMessage, time: receivedTime },
              ]);

              setAudioHtml(audioHtml);  // 음성 HTML 업데이트
            } catch (error) {
              console.error("Error fetching chatbot response:", error);
              setError(error.message);
            }
          };

          mediaRecorderRef.current.start();
          setIsRecording(true);
        })
        .catch((err) => {
          console.error("녹음 권한을 요청할 수 없습니다.", err);
        });
    }
  };

  // 음성 녹음 중지
  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  // 전송한 메시지와 응답 메시지 기록
  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;

    const sentTime = getTimeOnly();  // 시:분만 추가
    const newMessage = { sender: "사용자", message: userInput, time: sentTime };
    setChatHistory((prevHistory) => [...prevHistory, newMessage]);

    setUserInput("");  // 입력창 비우기

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chatbotName: chatbotName,
          user_input: userInput,
          personality: personality,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "오류가 발생했습니다.");
      }

      const data = await response.json();
      const chatbotMessage = data.response;

      const receivedTime = getTimeOnly();  // 시:분만 추가
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: chatbotName || chatbotName, message: chatbotMessage, time: receivedTime },
      ]);
    } catch (error) {
      console.error("Error fetching chatbot response:", error);
      setError(error.message);
    }
  };

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000); // 1초마다 시간 갱신

    return () => clearInterval(interval);  // 컴포넌트 언마운트 시 interval 클리어
  }, []);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });  // 새 메시지 스크롤
    }
  }, [chatHistory]);

  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSendMessage();
    }
  };

  const sendMessage = (message) => {
    const sentTime = getTimeOnly();
    setChatHistory((prevHistory) => [
      ...prevHistory,
      { sender: "사용자", message, time: sentTime },
    ]);
    setUserInput('');
    // 서버로 사용자 메시지 전송 (필요시)
  };

  return (
    <div>
      <div>
        <h1>{chatbotName}와의 채팅</h1>
        <div>
          {chatHistory.map((msg, index) => (
            <div key={index}>
              <strong>{msg.sender} ({msg.time}): </strong>{msg.message}
            </div>
          ))}
        </div>
        {audioHtml && (
          <div dangerouslySetInnerHTML={{ __html: audioHtml }}></div>
        )}
        {error && <div>Error: {error}</div>}
      </div>
      
      <div>
        <button onClick={startRecording} disabled={isRecording}>
          {isRecording ? '녹음 중...' : '녹음 시작'}
        </button>
        <button onClick={stopRecording} disabled={!isRecording}>
          녹음 중지
        </button>
      </div>

      <div>
        <textarea
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          placeholder="메시지를 입력하세요"
        />
        <button onClick={() => sendMessage(userInput)}>보내기</button>
      </div>
    </div>
  );
};

export default Chat;
